# Bring the Hermes CORE online: postgres + redis + ollama, prove GPU, pull+test model.
# Open WebUI / Portainer are intentionally deferred. Safe to re-run.
$ErrorActionPreference = "Continue"
Set-Location C:\HermesLab\hermes

function Pull-WithRetry([string]$img, [int]$max = 40) {
    for ($i = 1; $i -le $max; $i++) {
        Write-Host ">> pulling $img (attempt $i/$max)" -ForegroundColor Cyan
        docker pull $img
        if ($LASTEXITCODE -eq 0) { Write-Host ">> $img OK" -ForegroundColor Green; return $true }
        Start-Sleep -Seconds 15
    }
    Write-Host ">> $img FAILED after $max attempts" -ForegroundColor Red
    return $false
}

Write-Host "===== STEP 1: pull core images =====" -ForegroundColor Magenta
$okP = Pull-WithRetry "postgres:16"
$okR = Pull-WithRetry "redis:7"
$okO = Pull-WithRetry "ollama/ollama:latest"
if (-not ($okP -and $okR -and $okO)) { Write-Host "CORE_PULL_FAILED"; exit 1 }

Write-Host "`n===== STEP 2: start core containers =====" -ForegroundColor Magenta
docker compose up -d postgres redis ollama
docker compose ps

Write-Host "`n===== STEP 3: wait for ollama server =====" -ForegroundColor Magenta
$ready = $false
for ($i = 1; $i -le 20; $i++) {
    docker exec ollama ollama list *> $null
    if ($LASTEXITCODE -eq 0) { $ready = $true; break }
    Start-Sleep -Seconds 3
}
Write-Host "ollama ready: $ready"

Write-Host "`n===== STEP 4: GPU visibility inside container =====" -ForegroundColor Magenta
docker exec ollama nvidia-smi --query-gpu=index,name,memory.total,driver_version --format=csv,noheader

Write-Host "`n===== STEP 5: pull model llama3.2:3b =====" -ForegroundColor Magenta
$okM = $false
for ($i = 1; $i -le 40; $i++) {
    Write-Host ">> ollama pull llama3.2:3b (attempt $i/40)" -ForegroundColor Cyan
    docker exec ollama ollama pull llama3.2:3b
    if ($LASTEXITCODE -eq 0) { $okM = $true; break }
    Start-Sleep -Seconds ([Math]::Min(30, 5 * $i))
}
Write-Host "model pulled: $okM"

Write-Host "`n===== STEP 6: the proof =====" -ForegroundColor Magenta
if ($okM) {
    docker exec ollama ollama run llama3.2:3b "Say Hermes is online in one sentence."
}

Write-Host "`n===== DONE =====" -ForegroundColor Green
docker compose ps
Write-Host "CORE_ONLINE_COMPLETE okP=$okP okR=$okR okO=$okO model=$okM"
======== end core-online.ps1
======== model-pull.ps1  sha256=614f33813533328f907472174418a09dd44bab10ad34d70e55f1bc9a49cf63bb bytes=750
# Pull the first model into Ollama (with retries for the flaky link), then test it.
$ErrorActionPreference = "Continue"
$model = "llama3.2:3b"

Write-Host "===== Pulling $model (up to 40 attempts) ====="
$ok = $false
for ($i = 1; $i -le 40; $i++) {
    Write-Host ">> pull $model (attempt $i/40)"
    docker exec ollama ollama pull $model
    if ($LASTEXITCODE -eq 0) { $ok = $true; break }
    Write-Host ">> attempt $i failed, retrying..."
    Start-Sleep -Seconds 5
}
if (-not $ok) { Write-Host "MODEL_PULL_FAILED"; exit 1 }

Write-Host "`n===== ollama list ====="
docker exec ollama ollama list

Write-Host "`n===== TEST PROMPT ====="
docker exec ollama ollama run $model "Say Hermes is online in one sentence."

Write-Host "`nHERMES_CORE_ONLINE"
======== end model-pull.ps1
